<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php'; require dirname(__DIR__).'/vendor/autoload.php';
$_SESSION['cart']=$_SESSION['cart']??[];$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['_csrf']??'',(string)($_POST['_csrf']??''))){http_response_code(419);exit('انتهت صلاحية الطلب.');}
 $id=(int)($_POST['product_id']??0);$action=(string)($_POST['action']??'');
 if($action==='remove'){unset($_SESSION['cart'][$id]);$notice='تم حذف المنتج من السلة.';}
 elseif($action==='update'&&isset($_SESSION['cart'][$id])){$qty=(int)($_POST['quantity']??1);try{$q=db()->prepare("SELECT stock_quantity-reserved_quantity available FROM products WHERE id=? AND status='active' AND compliance_status='approved'");$q->execute([$id]);$available=(int)$q->fetchColumn();if($qty<1||$qty>$available){$notice='الكمية المطلوبة غير متوفرة.';}else{$_SESSION['cart'][$id]=$qty;$notice='تم تحديث السلة.';}}catch(Throwable $e){$notice='تعذر تحديث السلة.';}}
}
$items=[];$total=0;
try{if($_SESSION['cart']){$ids=array_map('intval',array_keys($_SESSION['cart']));$marks=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT p.id,p.name,p.price,p.stock_quantity,p.reserved_quantity,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_primary DESC,sort_order LIMIT 1) image_path FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id IN ($marks) AND p.status='active' AND p.compliance_status='approved' AND c.is_active=1 AND c.compliance_status='approved'");$q->execute($ids);$items=$q->fetchAll();foreach($items as &$item){$item['quantity']=(int)($_SESSION['cart'][$item['id']]??0);$item['line_total']=(float)$item['price']*$item['quantity'];$total+=$item['line_total'];if($item['quantity']>(int)$item['stock_quantity']-(int)$item['reserved_quantity']){$item['warning']='الكمية المتاحة تغيرت؛ يرجى تعديلها.';}}unset($item);}}catch(Throwable $e){error_log($e->getMessage());$notice='تعذر تحميل السلة حالياً.';}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سلة المشتريات | الفخامة</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css"><style>.cart-row{display:grid;grid-template-columns:90px 1fr auto;gap:16px;align-items:center;padding:15px;border-bottom:1px solid #382a17}.cart-row img{width:90px;height:85px;object-fit:cover;border-radius:10px}.cart-row input{width:70px;padding:8px;background:#111;color:white;border:1px solid #49371c;border-radius:8px}.cart-actions{display:flex;gap:8px;align-items:center}.cart-total{text-align:left;padding:22px;font-size:23px;color:#f4c45e}.cart-panel{border:1px solid #49371c;border-radius:16px;background:#111;overflow:hidden}@media(max-width:600px){.cart-row{grid-template-columns:65px 1fr}.cart-row img{width:65px;height:65px}.cart-actions{grid-column:1/-1;justify-content:flex-start}.cart-total{text-align:right}}</style></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="./"><span class="brand-mark">ف</span><span><strong>الفخامة</strong><small>AL FAKHAMAH</small></span></a><a class="btn btn-outline" href="./">متابعة التسوق</a></div></header><main class="section"><div class="container"><span class="eyebrow">مشترياتك</span><h1>سلة المشتريات</h1><?php if(isset($_GET['added'])):?><div class="notice">تمت إضافة المنتج إلى السلة بنجاح.</div><?php endif;?><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><div class="cart-panel"><?php foreach($items as $item):?><div class="cart-row"><?php if($item['image_path']):?><img src="<?=e($item['image_path'])?>" alt="<?=e($item['name'])?>"><?php else:?><div class="image-placeholder">ف</div><?php endif;?><div><strong><?=e($item['name'])?></strong><div><?=number_format((float)$item['price'],2)?> ر.س</div><?php if(!empty($item['warning'])):?><small class="unavailable"><?=e($item['warning'])?></small><?php endif;?></div><div class="cart-actions"><form method="post"><input type="hidden" name="_csrf" value="<?=e(App\Security::csrfToken())?>"><input type="hidden" name="product_id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="update"><input type="number" name="quantity" min="1" value="<?=(int)$item['quantity']?>"><button class="btn btn-outline" type="submit">تحديث</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=e(App\Security::csrfToken())?>"><input type="hidden" name="product_id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="remove"><button class="btn btn-outline" type="submit">حذف</button></form><b><?=number_format((float)$item['line_total'],2)?> ر.س</b></div></div><?php endforeach;?><?php if(!$items):?><div class="empty-state"><h3>سلتك فارغة حالياً</h3><p>أضف المنتجات التي ترغب بها لتظهر هنا.</p><a class="btn btn-gold" href="./">تصفح المتجر</a></div><?php else:?><div class="cart-total">الإجمالي: <?=number_format($total,2)?> ر.س <p><a class="btn btn-gold" href="checkout.php">متابعة إلى إتمام الطلب</a></p></div><?php endif;?></div></div></main></body></html>